export function HomeLogo() {
  const params = useDialKit("Home Logo", {
    container: {
      _collapsed: false,
      size: [56, 24, 120, 1],
      radius: [24, 0, 50, 1],
      offsetX: [0, -80, 80, 1],
      offsetY: [0, -40, 40, 1],
      gap: [12, 0, 40, 1],
    },
    image: {
      _collapsed: false,
      scale: [78, 40, 200, 1],
      offsetX: [0, -40, 40, 1],
      offsetY: [0, -40, 40, 1],
      color: { type: "color" as const, default: "#ffffff" },
    },
    background: {
      _collapsed: false,
      color: { type: "color" as const, default: "#151e37" },
      opacity: [1, 0, 1, 0.01],
    },
    shadow: {
      _collapsed: false,
      offsetY: [14, 0, 40, 1],
      blur: [23, 0, 80, 1],
      spread: [0, -20, 20, 1],
      opacity: [0.25, 0, 1, 0.01],
    },
  });

  const { container, image, background, shadow } = params;
  const boxShadow = `0 ${shadow.offsetY}px ${shadow.blur}px ${shadow.spread}px rgba(0, 0, 0, ${shadow.opacity})`;
  const backgroundColor = hexToRgba(background.color, background.opacity);

  return (
    <div
      className="flex items-center"
      style={{
        gap: `${container.gap}px`,
        transform: `translate(${container.offsetX}px, ${container.offsetY}px)`,
      }}
    >
      <div
        className="overflow-hidden flex items-center justify-center shrink-0"
        style={{
          width: `${container.size}px`,
          height: `${container.size}px`,
          borderRadius: `${container.radius}%`,
          backgroundColor,
          boxShadow,
        }}
      >
        <svg
          viewBox="0 0 428 428"
          aria-hidden="true"
          style={{
            width: `${image.scale}%`,
            height: `${image.scale}%`,
            transform: `translate(${image.offsetX}px, ${image.offsetY}px)`,
          }}
        >
          <path d={LOGO_PATH} fill={image.color} />
        </svg>
      </div>
      <div className="min-w-0">
        <div className="text-base font-semibold text-foreground">Leptum</div>
        <div className="text-sm text-muted-foreground">Local-first productivity</div>
      </div>
    </div>
  );
}
